import {simulate,SCENARIOS,VERSION} from './core.mjs';
const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';
const worker=new Worker(new URL('./worker.mjs',import.meta.url),{type:'module'});
let data,report,baseData,request=0,playing=false,selected='W001',timer=null,settings={},candidate=null,pendingBase=null;
const colors={ink:'#213f36',green:'#466c42',orange:'#bc562f',muted:'#94a18b'};
const stories={shared:'Four wearers share a location and an injected signal change. Test whether the finding survives removing one witness.',workload:'Activity increases, so heart rate rises too. A useful detector should explain this with the personal activity baseline, rather than call it an environmental event.',sensor:'One instrument develops a positive offset. The individual flag should remain visible without turning into a shared-event claim.',dropout:'Packets disappear and one stream has low quality. Inspect the missing-data counters: silence is not evidence of normality.',drift:'All instruments develop the same offset. Quorum can still pass. The missing ambient shift is a clue, but this engine cannot identify the cause. This is a known failure case.',boundary:'A shared change straddles a grid boundary. A fixed-cell detector can miss it when each side has too few witnesses.',null:'No event is injected. This tests the baseline under ordinary simulated signal variation.'};
function status(s,error=false){$('status').textContent=s;$('status').classList.toggle('error',error);}
function svg(tag,attrs,parent,text){const el=document.createElementNS(NS,tag);for(const [k,v] of Object.entries(attrs))el.setAttribute(k,v);if(text!==undefined)el.textContent=text;parent.append(el);return el;}
function save(name,obj){const url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function analyzeDataset(next){candidate=next;const id=++request;status('Checking packets, fitting baselines, and challenging each finding…');worker.postMessage({id,dataset:next,settings});}
worker.onmessage=({data:reply})=>{if(reply.id!==request)return;if(reply.error){pendingBase=null;settings=report?.settings??{};status(reply.error,true);return;}data=candidate;report=reply.report;if(pendingBase){baseData=pendingBase;pendingBase=null;}const ids=[...new Set(data.samples.map(r=>r.device))].sort();if(!ids.includes(selected))selected=ids[0];
  $('device').replaceChildren(...ids.map(id=>new Option(id,id)));$('device').value=selected;
  const old=$('remove').value;$('remove').replaceChildren(new Option('Keep everyone',''),...[...new Set(baseData.samples.map(r=>r.device))].sort().map(id=>new Option(id,id)));$('remove').value=old;
  const end=Math.max(...data.samples.map(r=>r.t_s));$('time').max=end;$('time').min=report.baseline.start_s;if(Number($('time').value)>end)$('time').value=end;
  $('source').textContent=`${data.provenance?.kind==='synthetic'?'SYNTHETIC':'IMPORTED · UNVERIFIED'} · ${ids.length} WEARERS`;
  $('engine').textContent=`ENGINE ${VERSION}`;
  $('story').textContent=stories[data.provenance?.scenario]??'Imported recording. Examine baseline coverage, missing packets, and device behavior before interpreting a finding.';
  status(`${report.quality.accepted.toLocaleString()} packets checked · ${report.summary.shared_windows} shared windows · ${report.summary.robust_windows} survive every single-device removal`);render();
};
worker.onerror=()=>status('Analysis worker failed. Reload and use a smaller recording.',true);
function render(){if(!report)return;const t=Number($('time').value),frame=new Map();for(const r of data.samples)if(r.t_s<=t&&(!frame.has(r.device)||frame.get(r.device).t_s<r.t_s))frame.set(r.device,r);
  $('clock').textContent=`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;
  const current=report.windows.filter(w=>t>=w.end_s&&t<w.end_s+report.settings.window_s),active=current.filter(w=>w.detected),chosen=current.find(w=>w.detected)??current.find(w=>w.cell[0]===0&&w.cell[1]===0)??current[0];
  const xs=data.samples.map(r=>r.x_m),ys=data.samples.map(r=>r.y_m),cell=report.settings.cell_m;
  let xmin=Math.floor(Math.min(...xs)/cell)*cell,xmax=(Math.floor(Math.max(...xs)/cell)+1)*cell,ymin=Math.floor(Math.min(...ys)/cell)*cell,ymax=(Math.floor(Math.max(...ys)/cell)+1)*cell;
  const scale=Math.min(590/Math.max(xmax-xmin,cell),240/Math.max(ymax-ymin,cell));const px=x=>55+(x-xmin)*scale,py=y=>75+(y-ymin)*scale;
  $('cells').replaceChildren();$('markers').replaceChildren();const cells=new Map();for(const r of frame.values()){const key=`${Math.floor(r.x_m/cell)},${Math.floor(r.y_m/cell)}`;cells.set(key,[Math.floor(r.x_m/cell),Math.floor(r.y_m/cell)]);}
  let c=0;for(const [cx,cy] of cells.values()){const w=current.find(w=>w.cell[0]===cx&&w.cell[1]===cy),hot=w?.detected;svg('rect',{x:px(cx*cell),y:py(cy*cell),width:cell*scale,height:cell*scale,fill:hot?'#bc562f19':'#466c420a',stroke:hot?colors.orange:'#aab5a0','stroke-width':hot?2:1},$('cells'));svg('text',{x:px(cx*cell)+8,y:py(cy*cell)-13,class:'cell-label'},$('cells'),`CELL ${cx},${cy}`);c++;}
  for(const r of frame.values()){const fresh=t-r.t_s<=10,m=report.baseline.models[r.device],z=m?(r.hr_bpm-m.intercept-m.slope*r.activity)/m.scale:0,hot=fresh&&z>=report.settings.z_threshold&&t>=report.baseline.end_s;
    const g=svg('g',{class:'sensor',role:'button',tabindex:0,'aria-label':`Inspect ${r.device}`},$('markers'));
    svg('circle',{cx:px(r.x_m),cy:py(r.y_m),r:selected===r.device?9:6,fill:fresh?(hot?colors.orange:colors.green):'#e3e6d9',stroke:colors.ink,'stroke-width':selected===r.device?2:1},g);
    svg('title',{},g,`${r.device}: ${fresh?r.hr_bpm.toFixed(1)+' bpm':'no current packet'}`);if(selected===r.device)svg('text',{x:px(r.x_m)-4,y:py(r.y_m)-17},g,r.device);g.onclick=()=>inspect(r.device);g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();inspect(r.device);}};
  }
  const verdict=$('verdict');verdict.replaceChildren();const tag=document.createElement('span');tag.className=`tag ${active.length?'alert':''}`;tag.textContent=t<report.baseline.end_s?'Learning the baseline':active.length?`${active.length} shared-change cell${active.length>1?'s':''}`:'No shared flag in this window';verdict.append(tag);
  const h=document.createElement('h2');h.textContent=t<report.baseline.end_s?'Listen before concluding.':active.some(w=>w.robust)?'The witnesses agree.':active.length?'A shared change. Limited support.':'No shared conclusion.';verdict.append(h);
  const p=document.createElement('p');p.textContent=t<report.baseline.end_s?'These readings establish the normal activity relationship. No event decision is made here.':chosen?`Completed window ${chosen.start_s}–${chosen.end_s} s, cell ${chosen.cell.join(',')}: ${chosen.votes}/${chosen.eligible} eligible witnesses exceed the residual threshold. Ambient change: ${chosen.ambient_delta_c===null?'unavailable':chosen.ambient_delta_c.toFixed(1)+' °C'}. ${chosen.robust?'Every single-device removal preserves the flag.':chosen.detected?'Removing some witnesses breaks support.':'Insufficient evidence for a shared event.'}`:'No completed post-baseline evidence window is available at this time.';verdict.append(p);
  $('peer-list').replaceChildren();for(const peer of chosen?.peers??[]){const div=document.createElement('div');div.className='peer';const a=document.createElement('span');a.textContent=peer.device;const b=document.createElement('span');b.className=peer.z>=report.settings.z_threshold?'high':'';b.textContent=`${peer.z.toFixed(2)} residual · ${peer.eligible?'eligible':'excluded'}`;div.append(a,b);$('peer-list').append(div);}
  $('quality').replaceChildren();for(const [label,value] of [['Missing sequence numbers',report.quality.missing_packets],['Duplicate packets ignored',report.quality.duplicates],['Out-of-order arrivals',report.quality.out_of_order],['Low-quality readings excluded',report.quality.low_quality],['Activity outside baseline',report.quality.extrapolated],['Devices without baseline',report.baseline.excluded.length]]){const row=document.createElement('div');row.className='quality-row';const a=document.createElement('span');a.textContent=label;const b=document.createElement('b');b.textContent=value.toLocaleString();row.append(a,b);$('quality').append(row);}
  trace(t);
}
function trace(t){const rows=data.samples.filter(r=>r.device===selected),m=report.baseline.models[selected],canvas=$('trace');canvas.replaceChildren();$('device-title').textContent=`Wearer ${selected}`;if(!rows.length)return;
  const maxT=Math.max(1,Number($('time').max)),pred=r=>m?m.intercept+m.slope*r.activity:r.hr_bpm;const values=rows.flatMap(r=>[r.hr_bpm,pred(r)]),low=Math.floor(Math.min(...values)/10)*10-5,high=Math.ceil(Math.max(...values)/10)*10+5,x=r=>40+r.t_s/maxT*560,y=v=>145-(v-low)/(high-low)*125;
  for(let v=Math.ceil(low/10)*10;v<=high;v+=20){svg('line',{x1:40,x2:600,y1:y(v),y2:y(v),stroke:'#c9cdbf'},canvas);svg('text',{x:2,y:y(v)+3,fill:'#647269','font-size':9},canvas,String(v));}
  svg('rect',{x:40,y:14,width:report.settings.baseline_s/maxT*560,height:133,fill:'#466c420d'},canvas);
  const path=fn=>rows.map((r,i)=>`${i?'L':'M'}${x(r).toFixed(1)},${y(fn(r)).toFixed(1)}`).join(' ');
  if(m)svg('path',{d:path(pred),fill:'none',stroke:colors.green,'stroke-dasharray':'5 4','stroke-width':1.5},canvas);
  svg('path',{d:path(r=>r.hr_bpm),fill:'none',stroke:colors.orange,'stroke-width':1.7},canvas);svg('line',{x1:40+t/maxT*560,x2:40+t/maxT*560,y1:10,y2:150,stroke:colors.ink},canvas);
  $('model').textContent=m?`Baseline ${m.samples} packets · scale ${m.scale.toFixed(1)} bpm`:'No supported baseline';
}
function inspect(id){selected=id;$('device').value=id;render();}
function generate(){const seed=Number($('seed').value);if(!Number.isSafeInteger(seed)||seed<0||seed>4294967295){status('Seed must be an integer from 0 to 4294967295.',true);return;}stop();pendingBase=null;settings={};$('remove').value='';baseData=simulate({scenario:$('scenario').value,seed});$('time').value=300;analyzeDataset(baseData);}
function stop(){playing=false;clearInterval(timer);$('play').textContent='▶';$('play').setAttribute('aria-label','Play replay');}
$('generate').onclick=generate;$('scenario').onchange=generate;$('time').oninput=()=>{stop();render();};$('device').onchange=()=>inspect($('device').value);
$('play').onclick=()=>{if(playing){stop();return;}playing=true;$('play').textContent='Ⅱ';$('play').setAttribute('aria-label','Pause replay');if(Number($('time').value)>=Number($('time').max))$('time').value=$('time').min;timer=setInterval(()=>{const t=Math.min(Number($('time').max),Number($('time').value)+5);$('time').value=t;render();if(t>=Number($('time').max))stop();},180);};
$('remove').onchange=()=>{stop();const id=$('remove').value;analyzeDataset({...baseData,samples:baseData.samples.filter(r=>r.device!==id)});};
$('export').onclick=()=>{if(report)save('canopy-capsule.json',{schema:'canopy-capsule/1',dataset:data,settings,report});};$('report').onclick=()=>{if(report)save('canopy-report.json',report);};
$('file').onchange=async()=>{const f=$('file').files[0];if(!f)return;try{if(f.size>10*1024*1024)throw Error('Browser file limit is 10 MiB. Use the local CLI for larger files.');const input=JSON.parse(await f.text()),d=input.schema==='canopy-capsule/1'?input.dataset:input;if(!Array.isArray(d?.samples)||d.samples.length>50000)throw Error('Browser limit is 50,000 samples. Use the local CLI for larger recordings.');settings=input.schema==='canopy-capsule/1'?(input.settings??{}):{};stop();pendingBase=d;$('remove').value='';analyzeDataset(d);}catch(e){status(e.message,true);}finally{$('file').value='';}};
for(const id of ['about','method'])$(id).onclick=()=>$('guide').showModal();$('close-guide').onclick=()=>$('guide').close();$('guide').onclick=e=>{if(e.target===$('guide')){const b=$('guide').getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)$('guide').close();}};
if(location.hostname==='127.0.0.1'){const label=document.createElement('span');label.className='dark download';label.textContent='Local toolkit is running';document.querySelector('a.download').replaceWith(label);}
generate();
